// Bakes web/docs/*.md into a TypeScript module. On Vercel the docs pages read the files at build time, which is
// fine; on Cloudflare Workers there is no filesystem at all, not even during the build's render step, so the
// markdown has to travel inside the bundle. Runs before every build, right after sync-docs.
import { readFileSync, readdirSync, writeFileSync, existsSync } from "node:fs";
import { dirname, resolve } from "node:path";
import { fileURLToPath } from "node:url";

const here = dirname(fileURLToPath(import.meta.url));
const dir = resolve(here, "..", "docs");
const out = resolve(here, "..", "src", "lib", "docsFiles.ts");
if (!existsSync(dir)) {
  console.log("docs bundle: web/docs not found, leaving the existing bundle in place");
  process.exit(0);
}
const files = readdirSync(dir).filter((f) => f.endsWith(".md")).sort();
const entries = files.map((f) => `  ${JSON.stringify(f)}: ${JSON.stringify(readFileSync(resolve(dir, f), "utf8"))},`).join("\n");
writeFileSync(
  out,
  `// Generated by scripts/build-docs-bundle.mjs. Do not edit: the source is the repository's docs/ folder.\n` +
    `export const DOC_FILES: Record<string, string> = {\n${entries}\n};\n`,
);
console.log(`docs bundle: ${files.length} markdown file(s) into src/lib/docsFiles.ts`);
